#Requires -Version 5.1
<#
.SYNOPSIS
  DeepSeek Harness (dsh web) 一键安装器
.DESCRIPTION
  本脚本完成:
    1. Node.js 引导: 本机已有 Node >= 20.19 则复用; 否则从 nodejs.org 官方源下载
       便携版 Node (无需管理员权限), 并做 SHA256 完整性校验。
    2. 安装 DeepSeek Harness CLI: npm 安装官方 @deepseek-ai/dsh 包到
       %LOCALAPPDATA%\DeepSeekHarness\npm (固定版本, 不影响系统 npm 全局目录)。
    3. 生成静默自启脚本与桌面打开脚本 (无窗口启动 "dsh web --no-open")。
    4. 创建桌面快捷方式与开机自启快捷方式。
    5. 启动服务并打开 Web GUI (http://127.0.0.1:3080/ 默认)。
  Uninstall 模式: 停止本安装器启动的服务进程、删除快捷方式与安装目录,
  不删除用户会话数据 (~/.dsh)。
.PARAMETER Workspace
  服务器工作目录 (影响新会话的默认 workspace), 默认用户主目录。
.PARAMETER Port
  Web GUI 端口, 默认 3080。
.PARAMETER Version
  要安装的 @deepseek-ai/dsh 版本, 默认 0.1.5-rc.3。
.PARAMETER NodeVersion
  无可用 Node 时下载的便携版版本, 默认 v22.19.0。
.PARAMETER NoAutostart
  不创建开机自启快捷方式。
.PARAMETER NoDesktopShortcut
  不创建桌面快捷方式。
.PARAMETER NoStart
  安装完成后不启动服务。
.PARAMETER NoOpen
  安装完成后不自动打开 GUI (仅当 -NoStart 未指定时有意义)。
.PARAMETER Uninstall
  卸载模式: 停止本安装器启动的服务并删除相关文件与快捷方式。
.PARAMETER Test
  沙盒测试模式: 所有目录 (安装目录/快捷方式/DSH 数据) 重定向到 %TEMP%,
  端口默认 3093, 不打开浏览器。仅用于开发验证。
.EXAMPLE
  powershell -NoProfile -ExecutionPolicy Bypass -Command "irm https://cdn.jsdelivr.net/gh/squirrelmedia/dsh-oneclick@latest/install.ps1 | iex"
#>
[CmdletBinding()]
param(
    [string]$Workspace,
    [int]$Port = 3080,
    [string]$Version = '0.1.5-rc.3',
    [string]$NodeVersion = 'v22.19.0',
    [switch]$NoAutostart,
    [switch]$NoDesktopShortcut,
    [switch]$NoStart,
    [switch]$NoOpen,
    [switch]$Uninstall,
    [switch]$Test
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$script:NodeMin = '20.19.0'
$script:NodeZipUrl = @{
    'x64'   = "https://nodejs.org/dist/$NodeVersion/node-$NodeVersion-win-x64.zip"
    'arm64' = "https://nodejs.org/dist/$NodeVersion/node-$NodeVersion-win-arm64.zip"
}
$script:NodeZipSha = @{
    'x64'   = 'ea3fad0e67a991d8477d8c01344b56e69c676ccb733f065b22436994b1253f86'
    'arm64' = 'e4a7336010d58ff35b53d9dd5869095c56089c70913cf22508cf8183593e56b2'
}
# dsh.ico (DeepSeek Harness 图标, 由官方前端 favicon.svg 生成), base64 注入于构建时
$script:IconBase64 = ''

function Write-Step([string]$text) {
    Write-Host "==> $text" -ForegroundColor Cyan
}
function Write-Ok([string]$text) {
    Write-Host "    [OK] $text" -ForegroundColor Green
}
function Write-WarnMsg([string]$text) {
    Write-Host "    [!] $text" -ForegroundColor Yellow
}
function Write-Fail([string]$text) {
    Write-Host "    [XX] $text" -ForegroundColor Red
}

# 快速 TCP 端口探测 (500ms 超时)
function Test-PortOpen([int]$port) {
    try {
        $client = New-Object System.Net.Sockets.TcpClient
        $async = $client.BeginConnect('127.0.0.1', $port, $null, $null)
        $ok = $async.AsyncWaitHandle.WaitOne(500)
        if ($ok -and $client.Connected) { $client.Close(); return $true }
        $client.Close(); return $false
    } catch { return $false }
}

function Get-NodeVersionOf([string]$exe) {
    try {
        $raw = (& $exe --version 2>$null | Out-String).Trim()
        if ($raw -match '^v?(\d+\.\d+\.\d+)') {
            return [version]$Matches[1]
        }
    } catch { }
    return $null
}

function Get-DshInstalledVersion([string]$exe, [string]$bin) {
    if (-not (Test-Path $bin)) { return $null }
    try {
        $raw = (& $exe $bin --version 2>$null | Out-String).Trim()
        if ($raw) { return $raw }
    } catch { }
    return $null
}

# ---------------- Uninstall 分支 ----------------
if ($Uninstall) {
    if ($Test) { throw 'Uninstall 与 Test 不能同时使用' }
    Write-Step '开始卸载 DeepSeek Harness 一键安装'
    $helperDir = Join-Path $env:LOCALAPPDATA 'DeepSeekHarness'
    $dshBin = Join-Path $helperDir 'npm\node_modules\@deepseek-ai\dsh\lib\bin.js'
    Write-Step '停止本安装器启动的服务进程'
    $killed = 0
    try {
        Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" -ErrorAction SilentlyContinue |
            Where-Object { $_.CommandLine -and $_.CommandLine.IndexOf($dshBin, [StringComparison]::OrdinalIgnoreCase) -ge 0 } |
            ForEach-Object {
                try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue; $killed++ } catch { }
            }
    } catch { }
    Write-Ok "已停止 $killed 个进程"
    Write-Step '删除快捷方式'
    $desktopLnk = Join-Path ([Environment]::GetFolderPath('Desktop')) 'DeepSeek Harness.lnk'
    $startupLnk = Join-Path ([Environment]::GetFolderPath('Startup')) 'DeepSeek Harness.lnk'
    foreach ($lnk in @($desktopLnk, $startupLnk)) {
        if (Test-Path $lnk) { Remove-Item $lnk -Force; Write-Ok "删除 $lnk" }
    }
    Write-Step '删除安装目录'
    if (Test-Path $helperDir) { Remove-Item $helperDir -Recurse -Force; Write-Ok "删除 $helperDir" }
    Write-Host ''
    Write-Host '卸载完成。会话数据目录 (用户主目录下 .dsh) 已保留, 如不再需要可手动删除。'
    return
}

# ---------------- 根目录确定 ----------------
$isTest = [bool]$Test
if ($isTest) {
    $helperDir = Join-Path $env:TEMP 'dsh-oneclick-test'
    $desktopDir = Join-Path $helperDir 'Desktop'
    $startupDir = Join-Path $helperDir 'Startup'
    $dshHome = Join-Path $helperDir 'home'
    if ($Port -eq 3080) { $Port = 3093 }
} else {
    $helperDir = Join-Path $env:LOCALAPPDATA 'DeepSeekHarness'
    $desktopDir = [Environment]::GetFolderPath('Desktop')
    $startupDir = [Environment]::GetFolderPath('Startup')
    $dshHome = Join-Path $env:USERPROFILE '.dsh'
}

if (-not $Workspace) {
    $Workspace = if ($isTest) { Join-Path $helperDir 'workspace' } else { $env:USERPROFILE }
}
if (-not (Test-Path $Workspace)) {
    New-Item -ItemType Directory -Path $Workspace -Force | Out-Null
    Write-WarnMsg "工作目录不存在, 已创建: $Workspace"
}
New-Item -ItemType Directory -Path $helperDir -Force | Out-Null
$logDir = Join-Path $helperDir 'logs'
New-Item -ItemType Directory -Path $logDir -Force | Out-Null

Write-Host ''
Write-Host 'DeepSeek Harness 一键安装器' -ForegroundColor White
Write-Host "  模式:            $(if ($isTest) { '沙盒测试 (TEMP)' } else { '正式安装' })"
Write-Host "  安装目录:        $helperDir"
Write-Host "  工作目录:        $Workspace"
Write-Host "  GUI 端口:        $Port"
Write-Host "  DSH 版本:        $Version"
Write-Host "  自启/桌面快捷:   $(if ($NoAutostart) { '跳过' } else { '创建' })/$(if ($NoDesktopShortcut) { '跳过' } else { '创建' })"
Write-Host ''

# ---------------- 1. Node.js 引导 ----------------
Write-Step '检查 Node.js'
$nodeExe = $null
$systemNode = Get-Command node -ErrorAction SilentlyContinue
if ($systemNode) {
    $nodeVer = Get-NodeVersionOf $systemNode.Source
    if ($nodeVer -and $nodeVer -ge [version]$script:NodeMin) {
        $nodeExe = $systemNode.Source
        Write-Ok "复用本机 Node $nodeVer ($nodeExe)"
    } else {
        Write-WarnMsg "本机 Node 版本过低或不可用, 改用便携版 $NodeVersion"
    }
}
if (-not $nodeExe) {
    $arch = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { 'arm64' } else { 'x64' }
    $nodeRoot = Join-Path $helperDir 'node'
    $nodeExe = Join-Path $nodeRoot "node-$NodeVersion-win-$arch\node.exe"
    if (-not (Test-Path $nodeExe)) {
        $zipUrl = $script:NodeZipUrl[$arch]
        $zipPath = Join-Path $helperDir "node-$NodeVersion-win-$arch.zip"
        Write-Step "下载便携版 Node $NodeVersion ($arch, 约 35MB)"
        try {
            Invoke-WebRequest -Uri $zipUrl -OutFile $zipPath -UseBasicParsing -TimeoutSec 600
        } catch {
            Write-Fail "下载失败: $($_.Exception.Message)"
            Write-Host '请检查网络后重试, 或先自行安装 Node.js 20.19+ 再运行本脚本。'
            exit 1
        }
        Write-Step '校验 SHA256'
        $actual = (Get-FileHash -Path $zipPath -Algorithm SHA256).Hash.ToLower()
        $expect = $script:NodeZipSha[$arch]
        if ($actual -ne $expect) {
            Write-Fail "SHA256 不匹配! 期望 $expect 实际 $actual"
            Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
            exit 1
        }
        Write-Ok '校验通过'
        Write-Step '解压便携版 Node'
        New-Item -ItemType Directory -Path $nodeRoot -Force | Out-Null
        $tar = Join-Path $env:SystemRoot 'System32\tar.exe'
        if (Test-Path $tar) {
            & $tar -xf $zipPath -C $nodeRoot
            if ($LASTEXITCODE -ne 0) { throw "tar 解压失败 (exit $LASTEXITCODE)" }
        } else {
            Expand-Archive -Path $zipPath -DestinationPath $nodeRoot -Force
        }
        Remove-Item $zipPath -Force -ErrorAction SilentlyContinue
        Write-Ok "解压完成"
    }
    $portableVer = Get-NodeVersionOf $nodeExe
    if (-not $portableVer) { throw '便携版 Node 校验失败 (node.exe 无法运行)' }
    Write-Ok "便携版 Node $portableVer ($nodeExe)"
}
$npmCli = Join-Path (Split-Path -Parent $nodeExe) 'node_modules\npm\bin\npm-cli.js'
if (-not (Test-Path $npmCli)) { throw "未找到 npm: $npmCli" }

# ---------------- 2. 安装 DSH CLI ----------------
$npmDir = Join-Path $helperDir 'npm'
$dshBin = Join-Path $npmDir 'node_modules\@deepseek-ai\dsh\lib\bin.js'
$installedVer = Get-DshInstalledVersion $nodeExe $dshBin
if ($installedVer -eq $Version) {
    Write-Step 'DSH CLI 已安装'
    Write-Ok "@deepseek-ai/dsh@$installedVer 已就绪, 跳过 npm 安装"
} else {
    if ($installedVer) { Write-Step "已装版本 $installedVer, 升级到 $Version" }
    else { Write-Step "npm 安装 @deepseek-ai/dsh@$Version" }
    New-Item -ItemType Directory -Path $npmDir -Force | Out-Null
    '{}' | Set-Content -Path (Join-Path $npmDir 'package.json') -Encoding ascii
    & $nodeExe $npmCli install --prefix $npmDir --no-save --no-audit --no-fund "@deepseek-ai/dsh@$Version"
    if ($LASTEXITCODE -ne 0) {
        Write-Fail "npm 安装失败 (exit $LASTEXITCODE), 请检查网络或 npm registry 配置"
        exit 1
    }
    if (-not (Test-Path $dshBin)) { throw "安装后未找到 $dshBin" }
    Write-Ok "安装完成: @deepseek-ai/dsh@$Version"
}

# ---------------- 3. 图标 ----------------
Write-Step '写入图标'
$iconPath = Join-Path $helperDir 'dsh.ico'
try {
    [IO.File]::WriteAllBytes($iconPath, [Convert]::FromBase64String($script:IconBase64))
    Write-Ok "写入 $iconPath"
} catch {
    Write-WarnMsg "图标写入失败 ($($_.Exception.Message)), 快捷方式将使用默认图标"
    $iconPath = $null
}

# ---------------- 4. 生成 VBS 启动脚本 ----------------
Write-Step '生成启动脚本'
$autostartLog = Join-Path $logDir 'dsh-autostart.log'
$launcherLog = Join-Path $logDir 'dsh-launcher.log'
$serverLog = Join-Path $logDir 'dsh-server.log'

$silentVbs = @'
' DeepSeek Harness silent autostart (generated by the dsh-oneclick installer).
' Starts the Web GUI server hidden (no console window, no browser popup).
' Skips starting when a server is already listening on the GUI port.
Option Explicit

Const NODE_EXE   = "__NODE_EXE__"
Const DSH_BIN    = "__DSH_BIN__"
Const WORK_DIR   = "__WORK_DIR__"
Const GUI_PORT   = __GUI_PORT__
Const LOG_FILE   = "__AUTOSTART_LOG__"
Const SERVER_LOG = "__SERVER_LOG__"

Dim fso, shell, guiPort

Set fso   = CreateObject("Scripting.FileSystemObject")
Set shell = CreateObject("WScript.Shell")

guiPort = GUI_PORT

EnsureDir fso.GetParentFolderName(LOG_FILE)

If IsPortListening(guiPort) Then
    WriteLog "server already running on port " & guiPort & " - nothing to do"
    WScript.Quit 0
End If

' Let the logon desktop settle before a heavy server process starts.
WScript.Sleep 3000

If IsPortListening(guiPort) Then
    WriteLog "server appeared while waiting - nothing to do"
    WScript.Quit 0
End If

shell.CurrentDirectory = WORK_DIR
WriteLog "starting dsh web (silent, --no-open) ..."
On Error Resume Next
shell.Run "cmd /c " & Q(Q(NODE_EXE) & " " & Q(DSH_BIN) & " web --no-open --port " & guiPort & " >> " & Q(SERVER_LOG) & " 2>&1"), 0, False
If Err.Number <> 0 Then
    WriteLog "error: could not launch the server: " & Err.Description
    Err.Clear
End If
On Error GoTo 0

Dim i
For i = 1 To 60
    WScript.Sleep 1000
    If IsPortListening(guiPort) Then Exit For
Next
If IsPortListening(guiPort) Then
    WriteLog "started: server listening on port " & guiPort & " after " & i & "s"
Else
    WriteLog "warning: port " & guiPort & " not listening after 60s (see dsh-server.log)"
End If

Sub EnsureDir(path)
    On Error Resume Next
    If Not fso.FolderExists(path) Then fso.CreateFolder(path)
    Err.Clear
    On Error GoTo 0
End Sub

Sub WriteLog(message)
    Dim f
    On Error Resume Next
    Set f = fso.OpenTextFile(LOG_FILE, 8, True)
    If Err.Number = 0 Then
        f.WriteLine "[" & Now & "] " & message
        f.Close
    End If
    Err.Clear
    On Error GoTo 0
End Sub

Function Q(text)
    Q = Chr(34) & text & Chr(34)
End Function

' Listening probe over loopback HTTP: any HTTP response (200/303/401) proves the
' port is served. No temp file and no child process, so concurrent scripts cannot
' race on a shared file and boot-time polling stays cheap.
Function IsPortListening(portNumber)
    Dim http
    IsPortListening = False
    On Error Resume Next
    Set http = CreateObject("WinHttp.WinHttpRequest.5.1")
    If Err.Number <> 0 Then
        Err.Clear
        Exit Function
    End If
    http.SetProxy 1, "", ""
    Err.Clear
    http.SetTimeouts 700, 700, 700, 700
    http.Open "GET", "http://127.0.0.1:" & portNumber & "/", False
    If Err.Number = 0 Then
        http.Send
        If Err.Number = 0 Then IsPortListening = True
    End If
    Err.Clear
    On Error GoTo 0
End Function
'@

$openVbs = @'
' DeepSeek Harness desktop launcher (generated by the dsh-oneclick installer).
' Opens the Web GUI in the default browser. When the server is not running,
' starts it silently first, waits for the port, then opens the authenticated
' URL printed by the server into the shared log. Falls back to the plain URL
' (works when the browser already holds the 30-day session cookie).
Option Explicit

Const NODE_EXE   = "__NODE_EXE__"
Const DSH_BIN    = "__DSH_BIN__"
Const WORK_DIR   = "__WORK_DIR__"
Const GUI_PORT   = __GUI_PORT__
Const LOG_FILE   = "__LAUNCHER_LOG__"
Const SERVER_LOG = "__SERVER_LOG__"

Dim fso, shell, guiPort, checkOnly, idx

Set fso   = CreateObject("Scripting.FileSystemObject")
Set shell = CreateObject("WScript.Shell")

guiPort = GUI_PORT
checkOnly = False
For idx = 0 To WScript.Arguments.Count - 1
    If WScript.Arguments(idx) = "/check" Then checkOnly = True
    If WScript.Arguments(idx) = "/port" Then
        If idx + 1 < WScript.Arguments.Count Then guiPort = CInt(WScript.Arguments(idx + 1))
    End If
Next

EnsureDir fso.GetParentFolderName(LOG_FILE)

Dim startedByUs, settle, i
startedByUs = False

' The autostart entry may be mid-boot: give it a moment before starting our own.
If Not IsPortListening(guiPort) Then
    For settle = 1 To 10
        WScript.Sleep 1000
        If IsPortListening(guiPort) Then Exit For
    Next
End If

If Not IsPortListening(guiPort) Then
    startedByUs = True
    WriteLog "server not running on port " & guiPort & " - starting it silently"
    shell.CurrentDirectory = WORK_DIR
    On Error Resume Next
    shell.Run "cmd /c " & Q(Q(NODE_EXE) & " " & Q(DSH_BIN) & " web --no-open --port " & guiPort & " >> " & Q(SERVER_LOG) & " 2>&1"), 0, False
    If Err.Number <> 0 Then
        WriteLog "error: could not launch the server: " & Err.Description
        Err.Clear
    End If
    On Error GoTo 0
    For i = 1 To 120
        WScript.Sleep 500
        If IsPortListening(guiPort) Then Exit For
    Next
    If Not IsPortListening(guiPort) Then
        WriteLog "error: server did not start listening within 60s"
        If Not checkOnly Then MsgBox "DeepSeek Harness could not be started within 60s." & vbCrLf & "Log: " & LOG_FILE, vbExclamation, "DeepSeek Harness"
        WScript.Quit 1
    End If
    WriteLog "server listening on port " & guiPort
End If

' The token URL is printed by the server once the tree finishes booting.
Dim tokenUrl
If startedByUs Then
    tokenUrl = WaitForTokenUrl(30)
Else
    tokenUrl = WaitForTokenUrl(3)
End If

Dim target
If tokenUrl <> "" Then
    If TokenUrlValid(tokenUrl) Then
        target = tokenUrl
        WriteLog "using validated token URL"
    Else
        target = ""
        WriteLog "log token URL stale - falling back to plain URL"
    End If
End If
If target = "" Then
    target = "http://127.0.0.1:" & guiPort & "/"
    WriteLog "opening plain URL (browser cookie path)"
End If

If checkOnly Then
    WriteLog "check: would open " & target
    WScript.Quit 0
End If

shell.Run target
WriteLog "opened " & target

Function WaitForTokenUrl(seconds)
    Dim waited, url
    For waited = 1 To seconds * 2
        url = LastTokenUrl()
        If url <> "" Then
            WaitForTokenUrl = url
            Exit Function
        End If
        WScript.Sleep 500
    Next
    WaitForTokenUrl = ""
End Function

Function LastTokenUrl()
    Dim f, line, pos, prefix, c, ch
    LastTokenUrl = ""
    prefix = "http://127.0.0.1:" & guiPort & "/?token="
    If Not fso.FileExists(SERVER_LOG) Then Exit Function
    Set f = fso.OpenTextFile(SERVER_LOG, 1)
    Do Until f.AtEndOfStream
        line = f.ReadLine
        pos = InStr(line, prefix)
        If pos > 0 Then
            LastTokenUrl = ""
            For c = pos To Len(line)
                ch = Mid(line, c, 1)
                If ch = " " Or ch = vbTab Then Exit For
                LastTokenUrl = LastTokenUrl & ch
            Next
        End If
    Loop
    f.Close
End Function

Function TokenUrlValid(url)
    Dim http
    TokenUrlValid = False
    On Error Resume Next
    Set http = CreateObject("WinHttp.WinHttpRequest.5.1")
    If Err.Number <> 0 Then
        Err.Clear
        Exit Function
    End If
    http.Option(6) = False
    http.Open "GET", url, False
    http.Send
    If Err.Number <> 0 Then
        Err.Clear
        Exit Function
    End If
    On Error GoTo 0
    TokenUrlValid = (http.Status = 303)
End Function

Sub EnsureDir(path)
    On Error Resume Next
    If Not fso.FolderExists(path) Then fso.CreateFolder(path)
    Err.Clear
    On Error GoTo 0
End Sub

Sub WriteLog(message)
    Dim f
    On Error Resume Next
    Set f = fso.OpenTextFile(LOG_FILE, 8, True)
    If Err.Number = 0 Then
        f.WriteLine "[" & Now & "] " & message
        f.Close
    End If
    Err.Clear
    On Error GoTo 0
End Sub

Function Q(text)
    Q = Chr(34) & text & Chr(34)
End Function

' Listening probe over loopback HTTP: any HTTP response (200/303/401) proves the
' port is served. No temp file and no child process, so concurrent scripts cannot
' race on a shared file and boot-time polling stays cheap.
Function IsPortListening(portNumber)
    Dim http
    IsPortListening = False
    On Error Resume Next
    Set http = CreateObject("WinHttp.WinHttpRequest.5.1")
    If Err.Number <> 0 Then
        Err.Clear
        Exit Function
    End If
    http.SetProxy 1, "", ""
    Err.Clear
    http.SetTimeouts 700, 700, 700, 700
    http.Open "GET", "http://127.0.0.1:" & portNumber & "/", False
    If Err.Number = 0 Then
        http.Send
        If Err.Number = 0 Then IsPortListening = True
    End If
    Err.Clear
    On Error GoTo 0
End Function
'@

$silentVbsPath = Join-Path $helperDir 'dsh-silent-start.vbs'
$openVbsPath = Join-Path $helperDir 'dsh-open.vbs'
$replacements = @{
    '__NODE_EXE__'      = $nodeExe
    '__DSH_BIN__'       = $dshBin
    '__WORK_DIR__'      = $Workspace
    '__GUI_PORT__'      = [string]$Port
    '__AUTOSTART_LOG__' = $autostartLog
    '__LAUNCHER_LOG__'  = $launcherLog
    '__SERVER_LOG__'    = $serverLog
}
foreach ($key in $replacements.Keys) {
    $silentVbs = $silentVbs.Replace($key, $replacements[$key])
    $openVbs = $openVbs.Replace($key, $replacements[$key])
}
[IO.File]::WriteAllText($silentVbsPath, $silentVbs, [Text.Encoding]::ASCII)
[IO.File]::WriteAllText($openVbsPath, $openVbs, [Text.Encoding]::ASCII)
Write-Ok "写入 $silentVbsPath"
Write-Ok "写入 $openVbsPath"

# ---------------- 5. 快捷方式 ----------------
function New-DshShortcut([string]$lnkPath, [string]$vbsPath, [string]$description) {
    $ws = New-Object -ComObject WScript.Shell
    $shortcut = $ws.CreateShortcut($lnkPath)
    $shortcut.TargetPath = Join-Path $env:SystemRoot 'System32\wscript.exe'
    $shortcut.Arguments = '"' + $vbsPath + '"'
    $shortcut.WorkingDirectory = $Workspace
    if ($iconPath) { $shortcut.IconLocation = "$iconPath,0" }
    $shortcut.Description = $description
    $shortcut.Save()
}
if (-not $NoDesktopShortcut) {
    Write-Step '创建桌面快捷方式'
    New-Item -ItemType Directory -Path $desktopDir -Force | Out-Null
    New-DshShortcut (Join-Path $desktopDir 'DeepSeek Harness.lnk') $openVbsPath 'DeepSeek Harness Web GUI'
    Write-Ok (Join-Path $desktopDir 'DeepSeek Harness.lnk')
}
if (-not $NoAutostart) {
    Write-Step '创建开机自启快捷方式'
    New-Item -ItemType Directory -Path $startupDir -Force | Out-Null
    New-DshShortcut (Join-Path $startupDir 'DeepSeek Harness.lnk') $silentVbsPath 'DeepSeek Harness silent autostart'
    Write-Ok (Join-Path $startupDir 'DeepSeek Harness.lnk')
}

# ---------------- 6. 启动服务 ----------------
if (-not $NoStart) {
    Write-Step '启动 DeepSeek Harness 服务'
    if ($isTest) {
        $env:DSH_HOME = $dshHome
    }
    Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\cscript.exe') -ArgumentList @('//nologo', $silentVbsPath) -WindowStyle Hidden | Out-Null
    $up = $false
    for ($i = 0; $i -lt 90; $i++) {
        Start-Sleep -Seconds 1
        if (Test-PortOpen $Port) { $up = $true; break }
    }
    if ($up) {
        Write-Ok "服务已启动并监听端口 $Port"
        # 等待 token URL 出现在服务器日志 (boot 完成标志)
        $tokenUrl = $null
        for ($i = 0; $i -lt 60; $i++) {
            Start-Sleep -Seconds 1
            if (Test-Path $serverLog) {
                $line = Get-Content $serverLog | Where-Object { $_ -match ('http://127.0.0.1:' + $Port + '/\?token=') } | Select-Object -Last 1
                if ($line) { $tokenUrl = ($line -replace '^.*(http://[^\s]+).*$', '$1'); break }
            }
        }
        if ($tokenUrl) {
            Write-Ok "认证地址已就绪"
            if ($isTest) {
                try {
                    $resp = Invoke-WebRequest -Uri $tokenUrl -UseBasicParsing -MaximumRedirection 5 -TimeoutSec 15
                    if ($resp.StatusCode -eq 200) { Write-Ok "token URL 验证通过 (HTTP 200)" }
                    else { Write-Fail "token URL 返回 $($resp.StatusCode)" }
                } catch {
                    Write-Fail "token URL 验证失败: $($_.Exception.Message)"
                }
                Write-Step '验证打开脚本 (check 模式)'
                & (Join-Path $env:SystemRoot 'System32\cscript.exe') //nologo $openVbsPath /check /port $Port | Out-Null
                Get-Content $launcherLog -Tail 3 | ForEach-Object { Write-Host "    $_" }
            }
        } else {
            Write-WarnMsg '60s 内未见 token URL 输出 (服务可能仍在初始化)'
        }
        if (-not $isTest -and -not $NoOpen) {
            Write-Step '打开 Web GUI'
            Start-Process -FilePath (Join-Path $env:SystemRoot 'System32\wscript.exe') -ArgumentList $openVbsPath | Out-Null
            if ($tokenUrl) { Write-Host "    如浏览器未自动打开, 请访问: $tokenUrl" }
        }
    } else {
        Write-Fail "90s 内端口 $Port 未就绪, 请查看日志: $autostartLog / $serverLog"
    }
} else {
    Write-WarnMsg '已跳过启动 (-NoStart)。之后可双击桌面快捷方式打开。'
}

# ---------------- 汇总 ----------------
Write-Host ''
Write-Host '安装完成。' -ForegroundColor Green
if (-not $isTest) {
    Write-Host "  打开 GUI:  双击桌面 DeepSeek Harness 快捷方式 (或访问 http://127.0.0.1:$Port/ )"
    Write-Host "  开机自启:  已注册于启动文件夹 (删除其中 DeepSeek Harness.lnk 即取消)"
    Write-Host "  卸载:      powershell -NoProfile -ExecutionPolicy Bypass -Command `"& ([scriptblock]::Create((irm 'https://cdn.jsdelivr.net/gh/squirrelmedia/dsh-oneclick@latest/install.ps1'))) -Uninstall`""
}
